size:
{
	return switch (value) {
		case _.length => 0:{
			"empty";
		};
		case _.toUpperCase() => "ABC":{
			"abc";
		};
		case ~/^[0-9]+$/.match(_) => true:{
			"digits";
		};
		case Std.parseInt(_) => n if (n != null && n < 0):{
			"negative";
		};
		case _ + "," + _ => "x,x":{
			"x";
		};
		case _:{
			"other";
		};
	};
}

nested:
{
	return switch (value) {
		case [first(_) => 1, _]:{
			"starts with one";
		};
		case ((_ : Array<Int>)) => []:{
			"none";
		};
		case _:{
			"other";
		};
	};
}

person:
{
	return switch (value) {
		case { name : _.length => 3, age : _ * 2 => 4 }:{
			"bob two";
		};
		case _:{
			"other";
		};
	};
}
